foreach (["select table_schema, table_name from information_schema.tables where table_schema not in (\x27pg_catalog\x27,\x27information_schema\x27)",
 "select table_name, column_name, data_type, is_nullable, column_default from information_schema.columns where table_schema=\x27public\x27 order by table_name, ordinal_position",
